class DashboardPageViewPanel(ViewPanel):

    def __init__(self, driver, version):
        self.driver = driver
        super(DashboardPageViewPanel, self).__init__(driver, version)

    def lock_element(self, lock_element, object_name, timeout):
        """
        This method will lock the given element object and return status

        :param lock_element str, type of element to be locked
        :param object_name: str, name of the element object that will lock
        :param timeout: int, timeout for the element be available to click

        :return: str, return the lock status of element object
        """
        self.click_enabled_element((By.XPATH, self.locator.LOCK_ELEMENT_XPATH.format(lock_element)), timeout)
        if self.element_exists((By.XPATH, self.locator.LOCK_UNLOCK_CLEAR_FILTER_XPATH), 5):
            self.click_enabled_element((By.XPATH, self.locator.LOCK_UNLOCK_CLEAR_FILTER_XPATH), timeout)
        self._select_filtered_element(object_name)
        self.click_enabled_element((By.XPATH, self.locator.OK_BUTTON_XPATH), timeout)
        self.wait_for_visibility((By.XPATH, self.locator.LOCK_OPERATION_STARTED_LABEL_XPATH), timeout)
        return self.get_text_by_xpath(self.locator.OPERATION_STATUS_LABEL_XPATH, timeout)

    def unlock_element(self, un_lock_element, object_name, timeout):
        """
        This method will unlock the given element object and return status

        :param un_lock_element str, type of element to be unlocked
        :param object_name: str, name of the element object that will unlock
        :param timeout: int, timeout for the element be available to click

        :return: str, return the unlock status of element object

        """
        self.click_enabled_element((By.XPATH, self.locator.UNLOCK_ELEMENT_XPATH.format(un_lock_element)), timeout)
        if self.element_exists((By.XPATH, self.locator.LOCK_UNLOCK_CLEAR_FILTER_XPATH), 5):
            self.click_enabled_element((By.XPATH, self.locator.LOCK_UNLOCK_CLEAR_FILTER_XPATH), timeout)
        self._select_filtered_element(object_name)
        self.click_enabled_element((By.XPATH, self.locator.OK_BUTTON_XPATH), timeout)
        self.wait_for_visibility((By.XPATH, self.locator.UN_LOCK_OPERATION_STARTED_LABEL_XPATH), timeout)
        return self.get_text_by_xpath(self.locator.OPERATION_STATUS_LABEL_XPATH, timeout)

    def reset_cu(self, timeout):
        """
        This keyword will reset the cu form dash board page

        :param timeout: int, timeout for the element be available to click

        :return: str, Status of the reset CU 'CU reset operation finished' or 'CU reset operation failed'
        """
        self.click_enabled_element((By.XPATH, self.locator.RESET_CU_XPATH), timeout)
        self.wait_for_visibility((By.XPATH, self.locator.RESET_CU_CONFORMATION_TITLE_XPATH), timeout)
        self.click_enabled_element((By.XPATH, self.locator.RESET_CU_CONFORMATION_TITLE_XPATH), timeout)
        self.wait_for_visibility((By.XPATH, self.locator.RESET_CU_CONFORMATION_MESSAGE_XPATH), timeout)
        self.click_enabled_element((By.XPATH, self.locator.OK_BUTTON_XPATH), timeout)
        self.wait_for_visibility((By.XPATH, self.locator.CU_RESET_STARTED_LABEL_XPATH), timeout)
        return self.get_text_by_xpath(self.locator.OPERATION_STATUS_LABEL_XPATH, timeout)

    def save_cu_configuration(self, timeout):
        """
        Keyword for saving cu configuration

        :param timeout: int, timeout for the element be available to click

        :return: str, path of file or string says "Save CU configuration failed" if failed
        """
        self.wait_for_visibility((By.XPATH, self.locator.SAVE_CU_CONFIGURATION_XPATH), timeout)
        self.click_enabled_element((By.XPATH, self.locator.SAVE_CU_CONFIGURATION_XPATH), timeout)
        self.wait_for_visibility((By.XPATH, self.locator.SAVE_CONFIG_STARTED_LABEL_XPATH), timeout)
        return self.get_text_by_xpath(self.locator.SAVE_CONFIG_FINISHED_LABEL_XPATH, timeout)

    def _select_filtered_element(self, object_name):
        element_name = object_name.split("/")[-1]
        self.insert_text_to_enable_element(self.locator.FILTER_XPATH, element_name)
        self.wait_for_visibility(
            (self.locator.SELECT_OBJECT_XPATH.format(element_name)), timeout=60)
        for element in self.driver.find_elements_by_xpath(
                self.locator.SELECT_OBJECT_XPATH.format(element_name)):
            element.click()
            if self._verify_selected_element(object_name):
                return True
            element.click()
        return False

    def _verify_selected_element(self, object_name):
        for element in self.driver.find_elements_by_xpath(
                self.locator.SELECTED_OBJECT_XPATH.format(object_name.split("/")[-1])):
            selected = element.text.split("/")
            for index in range(0, len(selected)):
                selected[index] = selected[index].replace(" ", "")
            return all(elem in selected for elem in object_name.split("/"))
        return False

    def get_dus_cell_info(self, timeout):
        """
        Keyword for getting DUs cell information under dashboard status page

        :param timeout: int, timeout for getting the status info

        :return: str, information of DUs
        """
        cell = self.wait_for_enable(self.locator.DU_CELL_INFO, timeout).text.split("\n")[0]
        self.click_enabled_element(self.locator.PRODUCT_LOGO, timeout)
        return cell

    def get_cells_info(self, timeout):
        """
        Keyword for getting Cells information under dashboard status page

        :param timeout: int, timeout for getting the status info

        :return: str, information of cells
        """
        cell = self.wait_for_enable(self.locator.CELLs_INFO, timeout).text.split("\n")[0]
        self.click_enabled_element(self.locator.PRODUCT_LOGO, timeout)
        return cell

    def get_X2_links_cell_info(self, timeout):
        """
        Keyword for getting X2 link cell information under dashboard status page

        :param timeout: int, timeout for getting the status info

        :return: str, information of cellsX2 link cell
        """
        cell = self.wait_for_enable(self.locator.X2_LINK_CELLs_INFO, timeout).text.split("\n")[0]
        self.click_enabled_element(self.locator.PRODUCT_LOGO, timeout)
        return cell

    def get_user_session_information(self, timeout):
        """
        This keyword will give the user session information
        :param timeout: int, timeout for getting user session information
        :return: dict: Return the dict of  user information attribute and values
        """
        self.click_enabled_element(self.locator.USER_COUNT_VIEW, timeout)
        user_info = ['user_name', 'role']
        user_info.extend(self.get_text_from_all_matching_elements(self.locator.USER_INFO_ATTRIBUTES))
        user_values = self.get_text_from_all_matching_elements(self.locator.USER_NAME_AND_ROLE)
        user_values.extend(self.get_text_from_all_matching_elements(self.locator.USER_INFO_VALUES))
        self.click_enabled_element(self.locator.USER_COUNT_VIEW, timeout)
        return dict(zip(user_info, user_values))

    def get_ng_links_cell_info(self, timeout):
        """
        Keyword for getting NG link cell information.

        :param timeout: int, timeout for getting the status info

        :return: str, NG link cell information
        """
        ng_link_cell_info = self.wait_for_enable(self.locator.NG_LINK_CELL_INFO, timeout).text.split("\n")[0]
        self.click_enabled_element(self.locator.PRODUCT_LOGO, timeout)
        return ng_link_cell_info
